@-moz-document domain("character.ai") {
body, html, div {
        background-color: #fdf0f2 !important;
    }
}

@-moz-document domain("character.ai") {
body, html, div {
        background-color: #fdf0f2 !important;
    }

    button {
        background-color: #f0fdfb !important;
        border-color: #d9ece9 !important; /* Optionnel : ajuste la bordure */
        color: #333 !important; /* Ajuste la couleur du texte si nécessaire */
    }

    /* Si certains boutons n'étaient pas affectés, essaie d'ajouter ça */
    [role="button"], .btn, .button {
        background-color: #f0fdfb !important;
        border-color: #d9ece9 !important;
        color: #333 !important;
    }
}

@-moz-document domain("character.ai") {
/* Camoufler les blocs noirs/gris */
    .skeleton, 
    .placeholder, 
    .lazyload, 
    .loading, 
    .animated-background, 
    .dynamic-image, 
    .image-placeholder, 
    .card-image, 
    .avatar-placeholder {
        background-color: #fdf0f2 !important;
        filter: brightness(100%) !important;
    }

    /* Enlever les bordures noires autour des cartes */
    .card, .card-content, .character-card, .chat-card {
        border: none !important;
        background-color: #fdf0f2 !important;
    }

    /* Cacher les éventuelles animations de chargement */
    .loading-spinner, 
    .loading-animation, 
    .skeleton-loader {
        display: none !important;
    }
}
